export type TaskTextKey = DashboardTextMessageKey<typeof taskMessages>;
export type TaskPluralKey = DashboardPluralMessageKey<typeof taskMessages>;

export const translateTask = (
  locale: DashboardLocale,
  key: TaskTextKey,
  variables?: DashboardMessageVariables,
): string => translateDashboardMessage(taskMessages, locale, key, variables);

export const translateTaskPlural = (
  locale: DashboardLocale,
  key: TaskPluralKey,
  count: number,
  variables?: DashboardMessageVariables,
): string => translateDashboardPlural(taskMessages, locale, key, count, variables);
